// queueTestStore opens a fresh Store, seeds the built-in tv module, and returns
// (store, registry). The tv module's metadata_sources (tv-parser empty AuthMode,
// kinopoisk CLIENT, tmdb SERVER) are the D-Q1 fixture (S8).
func queueTestStore(t *testing.T) (*store.Store, *module.Registry) {
	t.Helper()
	ctx := context.Background()
	s, err := store.Open(ctx, filepath.Join(t.TempDir(), "queue.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = s.Close() })
	reg, err := module.Open(ctx, s)
	if err != nil {
		t.Fatalf("module.Open: %v", err)
	}
	return s, reg
}

// putItem seeds an item with a mutable document map (marshaled opaque).
func putItem(t *testing.T, s *store.Store, id string, libID int64, status string, doc map[string]any) {
	t.Helper()
	docBytes, _ := json.Marshal(doc)
	if err := s.PutItem(context.Background(), store.Item{
		ID: id, ModuleID: "tv", LibraryID: libID, FileID: id,
		MediaType: "tv", Document: docBytes, Status: status,
	}); err != nil {
		t.Fatalf("PutItem %s: %v", id, err)
	}
}

// baseDoc is the minimal freshly-scanned document: parsed carries the TV path the
// chain reconstructs the IdentifyResult from (S7); no sources yet (pending work).
func baseDoc(relPath string) map[string]any {
	return map[string]any{
		"file_id":        "f",
		"module_type":    "tv",
		"schema_version": 1,
		"parsed":         map[string]any{"relative_path": relPath, "stem": "S01E01"},
	}
}

// succeedSrc is a MetadataSource that always succeeds, writing sources.<id>. It
// optionally captures the base handed to Match (the S7 reconstruct assertion).
type succeedSrc struct {
	id    string
	got   *scannerv1.IdentifyResult // captured base (nil unless Match ran)
	gotMu sync.Mutex
	calls int32
	delay time.Duration // >0 makes Match hold (lease no-double test)
}

var _ sdk.MetadataSource = (*succeedSrc)(nil)

func (s *succeedSrc) Match(_ context.Context, req *metadatav1.MatchRequest) (*metadatav1.MatchResult, error) {
	atomic.AddInt32(&s.calls, 1)
	s.gotMu.Lock()
	s.got = req.GetItem()
	s.gotMu.Unlock()
	if s.delay > 0 {
		time.Sleep(s.delay)
	}
	return &metadatav1.MatchResult{Applies: true}, nil
}
func (s *succeedSrc) BuildRequest(context.Context, *metadatav1.BuildRequestRequest) (*metadatav1.BuildRequestResponse, error) {
	return &metadatav1.BuildRequestResponse{}, nil
}
func (s *succeedSrc) Convert(context.Context, *metadatav1.ConvertRequest) (*metadatav1.ConvertResult, error) {
	md, _ := structpb.NewStruct(map[string]any{"title": s.id})
	return &metadatav1.ConvertResult{Metadata: md}, nil
}
func (s *succeedSrc) Merge(_ context.Context, req *metadatav1.MergeRequest) (*metadatav1.MergeResult, error) {
	return &metadatav1.MergeResult{Document: wrapNamespace(s.id, req.GetIncoming(), false)}, nil
}
func (s *succeedSrc) captured() *scannerv1.IdentifyResult {
	s.gotMu.Lock()
	defer s.gotMu.Unlock()
	return s.got
}

// mapResolver resolves each pluginID to its scripted source; an unknown id is
// "not loaded" (outcomeUnavailable). tv-module tests must seed BOTH queueable
// sources (tv-parser + tmdb) so neither busy-loops as a never-terminal unavailable.
type mapResolver map[string]sdk.MetadataSource

func (m mapResolver) resolver() metadataResolver {
	return func(pluginID, _ string) (sdk.MetadataSource, error) {
		if src, ok := m[pluginID]; ok {
			return src, nil
		}
		return nil, fmt.Errorf("plugin %q not loaded", pluginID)
	}
}

// pluginIDs collects the pluginIDs of a derived task list (order-insensitive
// comparison via sorted dedup).
func pluginIDs(tasks []queueTask) map[string]bool {
	out := make(map[string]bool, len(tasks))
	for _, tk := range tasks {
		out[tk.pluginID] = true
	}
	return out
}

// waitForStatus polls the item until it reaches want or the deadline elapses.
func waitForStatus(t *testing.T, s *store.Store, id, want string, timeout time.Duration) store.Item {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		it, err := s.GetItem(context.Background(), id)
		if err == nil && it.Status == want {
			return it
		}
		time.Sleep(time.Millisecond)
	}
	it, _ := s.GetItem(context.Background(), id)
	t.Fatalf("item %s status = %q, want %q (timeout %v)", id, it.Status, want, timeout)
	return it
}

// TestDerivation is the §4.4 derivation predicate (B8/S8/S1): the queue IS the
// derived set. Covers D-Q1 (CLIENT excluded; empty + SERVER queued), the
// namespace-done skip, and the ledger cooldown skip + eligibility re-derive.
func TestDerivation(t *testing.T) {
	ctx := context.Background()
	withFixedClock(t, time.Date(2026, 8, 3, 12, 0, 0, 0, time.UTC))
	s, reg := queueTestStore(t)
	libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})

	t.Run("D-Q1_CLIENT_excluded_empty_and_SERVER_queued", func(t *testing.T) {
		putItem(t, s, "i_dq1", libID, statusPending, baseDoc("Show/S01E01.mkv"))
		tasks, err := q.deriveLibrary(ctx, libID)
		if err != nil {
			t.Fatalf("deriveLibrary: %v", err)
		}
		got := pluginIDs(tasks)
		// tv-parser (empty AuthMode) + tmdb (SERVER) are pending; kinopoisk (CLIENT) is NOT.
		if !got["tv-parser"] || !got["tmdb"] {
			t.Fatalf("derivation = %v, want tv-parser + tmdb pending (D-Q1)", got)
		}
		if got["kinopoisk"] {
			t.Fatalf("kinopoisk (CLIENT) must NOT be queued (D-Q1 != CLIENT), got %v", got)
		}
	})

	t.Run("namespace_done_skipped", func(t *testing.T) {
		doc := baseDoc("Show/S01E02.mkv")
		doc["sources"] = map[string]any{"tv-parser": map[string]any{"title": "done"}}
		putItem(t, s, "i_done", libID, statusEnriched, doc)
		tasks, err := q.deriveLibrary(ctx, libID)
		if err != nil {
			t.Fatalf("deriveLibrary: %v", err)
		}
		for _, tk := range tasks {
			if tk.rowID == "i_done" && tk.pluginID == "tv-parser" {
				t.Fatalf("tv-parser re-derived for an item whose sources.tv-parser exists: %+v", tk)
			}
		}
	})

	t.Run("cooldown_skip_then_rederive_past_eligibility", func(t *testing.T) {
		t0 := now()
		putItem(t, s, "i_cool", libID, statusPending, baseDoc("Show/S01E03.mkv"))
		// seed a within-cooldown row (nextEligible = t0 + 7d).
		if err := s.RecordFailure(ctx, "i_cool", "tv-parser", ledgerExhausted, "boom",
			defaultMaxAttempts, t0.Add(defaultExhaustedCool)); err != nil {
			t.Fatalf("RecordFailure: %v", err)
		}
		tasks, err := q.deriveLibrary(ctx, libID)
		if err != nil {
			t.Fatalf("deriveLibrary: %v", err)
		}
		for _, tk := range tasks {
			if tk.rowID == "i_cool" && tk.pluginID == "tv-parser" {
				t.Fatalf("tv-parser derived within cooldown (loop-safety broken): %+v", tk)
			}
		}
		// advance the clock past eligibility -> the pair is re-derived.
		now = func() time.Time { return t0.Add(defaultExhaustedCool + time.Second) }
		tasks2, err := q.deriveLibrary(ctx, libID)
		if err != nil {
			t.Fatalf("deriveLibrary: %v", err)
		}
		found := false
		for _, tk := range tasks2 {
			if tk.rowID == "i_cool" && tk.pluginID == "tv-parser" {
				found = true
			}
		}
		if !found {
			t.Fatalf("tv-parser NOT re-derived after cooldown expired (AC-ledger(a) eligibility)")
		}
	})
}

// TestQueue_DrainToReady is AC-1 micro: a pending item whose queueable sources all
// succeed drains to ready with the namespace + provenance committed.
func TestQueue_DrainToReady(t *testing.T) {
	ctx := context.Background()
	s, reg := queueTestStore(t)
	libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	putItem(t, s, "i_drain", libID, statusPending, baseDoc("Show/S01E01.mkv"))

	tv := &succeedSrc{id: "tv-parser"}
	tmdb := &succeedSrc{id: "tmdb"}
	q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{Backoff: time.Millisecond})
	q.resolve = mapResolver{"tv-parser": tv, "tmdb": tmdb}.resolver()

	if err := q.Start(ctx); err != nil {
		t.Fatalf("Start: %v", err)
	}
	defer q.Stop()
	q.Notify(ctx, libID)

	it := waitForStatus(t, s, "i_drain", statusReady, 2*time.Second)
	doc := decodeDoc(it.Document)
	sources, _ := doc["sources"].(map[string]any)
	if _, ok := sources["tv-parser"]; !ok {
		t.Fatalf("sources.tv-parser absent after drain: %v", sources)
	}
	prov, _ := doc["_provenance"].(map[string]any)
	if len(prov) == 0 {
		t.Fatalf("_provenance absent after drain")
	}
	if q.Stats().Done < 1 {
		t.Fatalf("Stats.Done = %d, want >= 1", q.Stats().Done)
	}
}

// TestQueue_RetryToLedger is AC-ledger(a): a source that always fails exhausts its
// in-memory retries -> a terminal ledger row (exhausted, attempts=MaxAttempts,
// nextEligible ~= now+ExhaustedCool) is written and derivation skips the pair.
func TestQueue_RetryToLedger(t *testing.T) {
	ctx := context.Background()
	withFixedClock(t, time.Date(2026, 8, 3, 12, 0, 0, 0, time.UTC))
	s, reg := queueTestStore(t)
	libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	putItem(t, s, "i_retry", libID, statusPending, baseDoc("Show/S01E01.mkv"))

	// tv-parser always fails (exhausts); tmdb succeeds so the item still settles.
	q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{MaxAttempts: 3, Backoff: time.Millisecond})
	q.resolve = mapResolver{"tv-parser": &retrySource{id: "tv-parser", applies: true, failN: 99}, "tmdb": &succeedSrc{id: "tmdb"}}.resolver()

	if err := q.Start(ctx); err != nil {
		t.Fatalf("Start: %v", err)
	}
	defer q.Stop()
	q.Notify(ctx, libID)
	_ = waitForStatus(t, s, "i_retry", statusReady, 2*time.Second) // tmdb settles the item

	rows, err := s.ListFailures(ctx)
	if err != nil {
		t.Fatalf("ListFailures: %v", err)
	}
	var row store.FailureRow
	for _, r := range rows {
		if r.ItemID == "i_retry" && r.PluginID == "tv-parser" {
			row = r
		}
	}
	if row.ItemID == "" {
		t.Fatalf("no exhausted ledger row for (i_retry, tv-parser); rows=%v", rows)
	}
	if row.Status != ledgerExhausted {
		t.Fatalf("ledger status = %q, want %q", row.Status, ledgerExhausted)
	}
	if row.Attempts != 3 {
		t.Fatalf("ledger attempts = %d, want %d (MaxAttempts on first exhaustion)", row.Attempts, 3)
	}
	want := now().Add(defaultExhaustedCool)
	if row.NextEligibleAt.Before(now().Add(defaultExhaustedCool-time.Second)) || row.NextEligibleAt.After(want.Add(time.Second)) {
		t.Fatalf("NextEligibleAt = %v, want ~= now+ExhaustedCool (%v)", row.NextEligibleAt, want)
	}
	// derivation skips the exhausted pair (loop-safety).
	tasks, err := q.deriveLibrary(ctx, libID)
	if err != nil {
		t.Fatalf("deriveLibrary: %v", err)
	}
	for _, tk := range tasks {
		if tk.rowID == "i_retry" && tk.pluginID == "tv-parser" {
			t.Fatalf("exhausted pair re-derived (cooldown skip broken): %+v", tk)
		}
	}
}

// TestQueue_ResetOnSuccess is AC-ledger(b): a pair that had a ledger row later
// succeeds -> the row is deleted (reset-on-success, hot path near-zero writes).
func TestQueue_ResetOnSuccess(t *testing.T) {
	ctx := context.Background()
	s, reg := queueTestStore(t)
	libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	putItem(t, s, "i_reset", libID, statusPending, baseDoc("Show/S01E01.mkv"))
	// pre-seed an EXPIRED ledger row: the pair's cooldown has elapsed, so the
	// worker re-derives tv-parser, runs it, succeeds, and deletes the row
	// (reset-on-success). A still-warm row would be (correctly) skipped.
	if err := s.RecordFailure(ctx, "i_reset", "tv-parser", ledgerExhausted, "old",
		2, time.Now().UTC().Add(-time.Hour)); err != nil {
		t.Fatalf("RecordFailure: %v", err)
	}
	q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{MaxAttempts: 3, Backoff: time.Millisecond})
	q.resolve = mapResolver{"tv-parser": &succeedSrc{id: "tv-parser"}, "tmdb": &succeedSrc{id: "tmdb"}}.resolver()

	if err := q.Start(ctx); err != nil {
		t.Fatalf("Start: %v", err)
	}
	defer q.Stop()
	q.Notify(ctx, libID)
	_ = waitForStatus(t, s, "i_reset", statusReady, 2*time.Second)

	rows, err := s.ListFailures(ctx)
	if err != nil {
		t.Fatalf("ListFailures: %v", err)
	}
	for _, r := range rows {
		if r.ItemID == "i_reset" && r.PluginID == "tv-parser" {
			t.Fatalf("ledger row NOT cleared on success (reset-on-success broken): %+v", r)
		}
	}
}

// TestQueue_RestartResume is AC-ledger(c): the in-memory queue + leases vanish on
// restart; Start re-derives pending from items, and an in-cooldown pair is NOT
// re-derived into a loop (only per-session in-memory retry counters reset).
func TestQueue_RestartResume(t *testing.T) {
	ctx := context.Background()
	withFixedClock(t, time.Date(2026, 8, 3, 12, 0, 0, 0, time.UTC))
	s, reg := queueTestStore(t)
	libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	putItem(t, s, "i_resume", libID, statusPending, baseDoc("Show/S01E01.mkv"))

	run := func() *Queue {
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{MaxAttempts: 3, Backoff: time.Millisecond})
		q.resolve = mapResolver{"tv-parser": &succeedSrc{id: "tv-parser"}, "tmdb": &succeedSrc{id: "tmdb"}}.resolver()
		if err := q.Start(ctx); err != nil {
			t.Fatalf("Start: %v", err)
		}
		q.Notify(ctx, libID)
		_ = waitForStatus(t, s, "i_resume", statusReady, 2*time.Second)
		q.Stop()
		return q
	}
	run() // first session: drains to ready

	// seed a fresh exhausted row WITHIN cooldown; restart must NOT re-derive it.
	if err := s.RecordFailure(ctx, "i_resume", "tv-parser", ledgerExhausted, "boom",
		defaultMaxAttempts, now().Add(defaultExhaustedCool)); err != nil {
		t.Fatalf("RecordFailure: %v", err)
	}
	// also clear the namespace so the pair WOULD be pending if not for cooldown.
	clearDoc := baseDoc("Show/S01E01.mkv")
	b, _ := json.Marshal(clearDoc)
	_ = s.PutItem(ctx, store.Item{ID: "i_resume", ModuleID: "tv", LibraryID: libID,
		FileID: "i_resume", MediaType: "tv", Document: b, Status: statusPending})

	q2 := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
	tasks, err := q2.deriveLibrary(ctx, libID)
	if err != nil {
		t.Fatalf("deriveLibrary: %v", err)
	}
	for _, tk := range tasks {
		if tk.rowID == "i_resume" && tk.pluginID == "tv-parser" {
			t.Fatalf("in-cooldown pair re-derived after restart (loop-safety broken): %+v", tk)
		}
	}
}

// TestQueue_LeaseNoDouble is AC-lease (dispatch half): two concurrent workItem
// calls for the SAME item result in exactly one processing pass — the lease
// blocks the second while the first holds it (serialize-within-item). -race clean.
func TestQueue_LeaseNoDouble(t *testing.T) {
	ctx := context.Background()
	s, reg := queueTestStore(t)
	libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	putItem(t, s, "i_lease", libID, statusPending, baseDoc("Show/S01E01.mkv"))

	block := &succeedSrc{id: "tv-parser", delay: 40 * time.Millisecond} // hold the lease ~40ms
	q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{LeaseTTL: time.Minute, Backoff: time.Millisecond})
	q.resolve = mapResolver{"tv-parser": block, "tmdb": &succeedSrc{id: "tmdb"}}.resolver()

	var wg sync.WaitGroup
	start := make(chan struct{})
	for i := 0; i < 2; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			q.workItem(ctx, "i_lease")
		}()
	}
	close(start)
	wg.Wait()

	// Match ran exactly once for tv-parser: the second workItem was lease-blocked
	// for the full hold window (not a double-process).
	if calls := atomic.LoadInt32(&block.calls); calls != 1 {
		t.Fatalf("tv-parser Match calls = %d, want 1 (lease must serialize within-item)", calls)
	}
}

