// TestReconstructBase is S7/D-Q2: the worker rebuilds the per-item IdentifyResult
// from the PERSISTED document (Parsed out of doc["parsed"]); no re-probe. The
// captured base is the exact struct Match consumed.
func TestReconstructBase(t *testing.T) {
	t.Run("from_map_after_round_trip", func(t *testing.T) {
		doc := map[string]any{"parsed": map[string]any{"relative_path": "Show/S01E01.mkv", "season": 1.0}}
		base := reconstructBase(doc)
		f := base.GetParsed().GetFields()
		if rp := f["relative_path"].GetStringValue(); rp != "Show/S01E01.mkv" {
			t.Fatalf("relative_path = %q, want Show/S01E01.mkv", rp)
		}
	})
	t.Run("from_rawmessage_assembled", func(t *testing.T) {
		parsed, _ := json.Marshal(map[string]any{"stem": "S02E03"})
		doc := map[string]any{"parsed": json.RawMessage(parsed)}
		base := reconstructBase(doc)
		if s := base.GetParsed().GetFields()["stem"].GetStringValue(); s != "S02E03" {
			t.Fatalf("stem = %q, want S02E03", s)
		}
	})
	t.Run("empty_doc_safe", func(t *testing.T) {
		base := reconstructBase(map[string]any{})
		if base == nil || base.GetParsed() == nil {
			t.Fatalf("reconstructBase(empty) = %v, want non-nil IdentifyResult+Parsed", base)
		}
	})
}

// TestReconstructBase_DrivesMatch drives the reconstructed base through a fake
// source's Match (the worker's per-item path), asserting Match received the
// parsed Struct reconstructed from the persisted doc (S7 joint).
func TestReconstructBase_DrivesMatch(t *testing.T) {
	ctx := context.Background()
	s, reg := queueTestStore(t)
	libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	putItem(t, s, "i_base", libID, statusPending, baseDoc("Show/Special/S01E01.mkv"))

	cap := &succeedSrc{id: "tv-parser"}
	q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{Backoff: time.Millisecond})
	q.resolve = mapResolver{"tv-parser": cap, "tmdb": &succeedSrc{id: "tmdb"}}.resolver()
	if err := q.Start(ctx); err != nil {
		t.Fatalf("Start: %v", err)
	}
	defer q.Stop()
	q.Notify(ctx, libID)
	_ = waitForStatus(t, s, "i_base", statusReady, 2*time.Second)

	got := cap.captured()
	if got == nil {
		t.Fatal("Match never received a base (reconstruct not wired)")
	}
	if rp := got.GetParsed().GetFields()["relative_path"].GetStringValue(); rp != "Show/Special/S01E01.mkv" {
		t.Fatalf("reconstructed base Parsed.relative_path = %q, want the persisted path (S7)", rp)
	}
}

// TestTerminalCooldown is the §4.4 doubling schedule (B13): exhausted doubles
// per round (7d->14d->28d, capped at 365d); no_data is flat 30d.
func TestTerminalCooldown(t *testing.T) {
	cfg := withDefaults(QueueConfig{})
	day := 24 * time.Hour
	cases := []struct {
		name          string
		status        string
		priorAttempts int
		wantAttempts  int
		wantCool      time.Duration
	}{
		{"exhausted_round1", ledgerExhausted, 0, 3, 7 * day},
		{"exhausted_round2", ledgerExhausted, 3, 4, 14 * day},
		{"exhausted_round3", ledgerExhausted, 4, 5, 28 * day},
		{"exhausted_capped", ledgerExhausted, 40, 41, 365 * day},
		{"no_data_flat", ledgerNoData, 0, 3, 30 * day},
		{"no_data_no_doubling", ledgerNoData, 5, 6, 30 * day},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			attempts, cool := terminalCooldown(tc.status, tc.priorAttempts, cfg)
			if attempts != tc.wantAttempts {
				t.Fatalf("attempts = %d, want %d", attempts, tc.wantAttempts)
			}
			if cool != tc.wantCool {
				t.Fatalf("cooldown = %v, want %v", cool, tc.wantCool)
			}
		})
	}
}

// TestDerivationChainPriority covers the consumer half of the stored
// per-library parser chain (element-pages 3.1: the parser order defines the
// enrichment queue priority for collection-common sources). With no chain the
// derivation emits the module's queueable sources in config order (the seed
// default); after a SetLibraryChain reorder the same row's tasks emit in chain
// order. D-Q1 holds either way — the CLIENT source stays out of the queue
// whatever its chain position.
func TestDerivationChainPriority(t *testing.T) {
	ctx := context.Background()
	s, reg := queueTestStore(t)
	libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	putItem(t, s, "i_chain", libID, statusPending, baseDoc("Show/S01E09.mkv"))
	q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})

	rowTasks := func(t *testing.T) string {
		t.Helper()
		tasks, err := q.deriveLibrary(ctx, libID)
		if err != nil {
			t.Fatalf("deriveLibrary: %v", err)
		}
		ids := make([]string, 0, 2)
		for _, tk := range tasks {
			if tk.rowID == "i_chain" {
				ids = append(ids, tk.pluginID)
			}
		}
		return strings.Join(ids, ",")
	}

	// Absent chain: config order (tv-parser, kinopoisk, tmdb,
	// frame-grabber) with the D-Q1 CLIENT exclusion -> [tv-parser tmdb
	// frame-grabber] (the v2 tv seed adds frame-grabber at priority 4).
	if got := rowTasks(t); got != "tv-parser,tmdb,frame-grabber" {
		t.Fatalf("absent-chain derivation = %q, want %q (config order)", got, "tv-parser,tmdb,frame-grabber")
	}

	// Reorder the stored chain: derivation priority follows it.
	if err := s.SetLibraryChain(ctx, libID, []string{"tmdb", "tv-parser"}); err != nil {
		t.Fatalf("SetLibraryChain: %v", err)
	}
	// frame-grabber stays in config position after the reordered pair (the v2
	// tv seed adds it at priority 4; SetLibraryChain reorders the named two).
	if got := rowTasks(t); got != "tmdb,tv-parser,frame-grabber" {
		t.Fatalf("chain-ordered derivation = %q, want %q (chain order)", got, "tmdb,tv-parser,frame-grabber")
	}
}
